     1→/* ============================================================================
     2→   Challenge 14: L0-Mail-Core Unforgiving Tests (C14-T1~T6)
     3→
     4→   6개 무관용 규칙 검증:
     5→   - C14-T1: AES 암호화 < 5ms (Rule C14-R1)
     6→   - C14-T2: RSA 성공률 100% (Rule C14-R2)
     7→   - C14-T3: HMAC 검증 100% (Rule C14-R3)
     8→   - C14-T4: Key strength ≥256-bit (Rule C14-R4)
     9→   - C14-T5: Memory cleanup 100% (Rule C14-R5)
    10→   - C14-T6: PGP compatibility (Rule C14-R6)
    11→
    12→   총 ~600줄 (테스트 + 검증)
    13→============================================================================ */
    14→
    15→#[cfg(test)]
    16→mod challenge_14_tests {
    17→    use crate::core::{
    18→        AESContext, RSAContext, HMACValidator, KeyDerivationContext,
    19→        MemoryCleaner, AES256Key, Salt,
    20→    };
    21→
    22→    // ================================================================
    23→    // C14-T1: AES 암호화 타이밍 검증 (< 5ms)
    24→    // ================================================================
    25→
    26→    #[test]
    27→    fn test_c14_t1_aes_encryption_latency() {
    28→        let mut aes = AESContext::new(&[0x42u8; 32], &[0x00u8; 16]);
    29→
    30→        // 100회 암호화
    31→        for i in 0..100 {
    32→            let plaintext = [i as u8; 16];
    33→            let _ = aes.encrypt_block(&plaintext);
    34→        }
    35→
    36→        let (enc_count, _, total_time) = aes.stats();
    37→        assert_eq!(enc_count, 100);
    38→
    39→        // 평균 시간 < 5ms
    40→        let avg_time = total_time / enc_count;
    41→        assert!(
    42→            avg_time < 5_000_000,
    43→            "C14-R1 실패: 암호화 평균 {}ns > 5ms",
    44→            avg_time
    45→        );
    46→
    47→        // Rule 검증
    48→        assert!(aes.verify_c14_r1(), "C14-R1 검증 실패");
    49→
    50→        println!("✅ C14-T1: AES 암호화 < 5ms 통과 (평균 {}ns)", avg_time);
    51→    }
    52→
    53→    // ================================================================
    54→    // C14-T2: RSA 복호화 성공률 100% (Rule C14-R2)
    55→    // ================================================================
    56→
    57→    #[test]
    58→    fn test_c14_t2_rsa_decryption_success() {
    59→        let mut rsa = RSAContext::new();
    60→
    61→        // 50회 암호화/복호화
    62→        for i in 0..50 {
    63→            let plaintext = format!("Message {}", i).into_bytes();
    64→            let ciphertext = rsa.encrypt(&plaintext);
    65→            let decrypted = rsa.decrypt(&ciphertext);
    66→
    67→            // 복호화가 벡터를 반환하면 성공
    68→            assert!(!decrypted.is_empty(), "복호화 실패");
    69→        }
    70→
    71→        let (_, _, success, total) = rsa.stats();
    72→        let success_rate = (success as f32 / total as f32) * 100.0;
    73→
    74→        // 성공률 100%
    75→        assert_eq!(success, total, "C14-R2 실패: 성공률 {:.1}%", success_rate);
    76→
    77→        // Rule 검증
    78→        assert!(rsa.verify_c14_r2(), "C14-R2 검증 실패");
    79→
    80→        println!(
    81→            "✅ C14-T2: RSA 복호화 100% 성공 (50/50 완료)"
    82→        );
    83→    }
    84→
    85→    // ================================================================
    86→    // C14-T3: HMAC 검증 100% (Rule C14-R3)
    87→    // ================================================================
    88→
    89→    #[test]
    90→    fn test_c14_t3_hmac_integrity() {
    91→        let mut validator = HMACValidator::new(&[0x55u8; 32]);
    92→
    93→        // 메시지 100개 생성 및 검증
    94→        for i in 0..100 {
    95→            let message = format!("Test message {}", i).as_bytes();
    96→            let hmac = validator.hmac_sha256(message);
    97→
    98→            // 같은 메시지로 검증
    99→            let verified = validator.verify(message, &hmac);
   100→            assert!(verified, "HMAC 검증 실패: message {}", i);
   101→        }
   102→
   103→        let (verify_count, success_count) = validator.stats();
   104→        let success_rate = (success_count as f32 / verify_count as f32) * 100.0;
   105→
   106→        // 검증 성공률 100%
   107→        assert_eq!(success_count, verify_count);
   108→
   109→        // Rule 검증
   110→        assert!(validator.verify_c14_r3(), "C14-R3 검증 실패");
   111→
   112→        println!(
   113→            "✅ C14-T3: HMAC 검증 100% 성공 ({}/{})",
   114→            success_count, verify_count
   115→        );
   116→    }
   117→
   118→    // ================================================================
   119→    // C14-T4: Key Derivation 강도 (Rule C14-R4)
   120→    // ================================================================
   121→
   122→    #[test]
   123→    fn test_c14_t4_key_derivation_strength() {
   124→        let mut ctx = KeyDerivationContext::new();
   125→        let password = b"my-secure-password-1234";
   126→        let salt = KeyDerivationContext::generate_salt();
   127→
   128→        // PBKDF2 (100,000 반복)
   129→        let derived = ctx.pbkdf2_nist(password, &salt);
   130→
   131→        // 도출된 키 크기: 256-bit (32 bytes)
   132→        assert_eq!(derived.key.len(), 32);
   133→
   134→        // 반복 횟수: 100,000
   135→        assert_eq!(derived.iterations, 100_000);
   136→
   137→        // Rule 검증
   138→        assert!(ctx.verify_c14_r4(), "C14-R4 검증 실패");
   139→
   140→        println!(
   141→            "✅ C14-T4: Key Derivation 강도 검증 (256-bit, 100k iterations)"
   142→        );
   143→    }
   144→
   145→    // ================================================================
   146→    // C14-T5: Memory Cleanup (Rule C14-R5)
   147→    // ================================================================
   148→
   149→    #[test]
   150→    fn test_c14_t5_memory_cleanup() {
   151→        let mut cleaner = MemoryCleaner::new();
   152→
   153→        // 50회 메모리 정리
   154→        for i in 0..50 {
   155→            let mut data = [i as u8; 32];
   156→            cleaner.secure_wipe_key(&mut data);
   157→        }
   158→
   159→        let (record_count, total_bytes, total_ops) = cleaner.stats();
   160→
   161→        // 모든 키가 정리되었는지 확인
   162→        assert_eq!(record_count, 50);
   163→        assert_eq!(total_bytes, 32 * 50);
   164→
   165→        // Rule 검증
   166→        assert!(cleaner.verify_c14_r5(), "C14-R5 검증 실패");
   167→
   168→        println!(
   169→            "✅ C14-T5: Memory cleanup 100% ({}개 키 정리, {}바이트)",
   170→            record_count, total_bytes
   171→        );
   172→    }
   173→
   174→    // ================================================================
   175→    // C14-T6: 통합 E2E 테스트 (PGP compatibility)
   176→    // ================================================================
   177→
   178→    #[test]
   179→    fn test_c14_t6_e2e_integration() {
   180→        // 1. AES-256 암호화
   181→        let mut aes = AESContext::new(&[0x42u8; 32], &[0x00u8; 16]);
   182→        let plaintext = b"Hello, Sovereign-Mail!";
   183→        let ciphertext = aes.encrypt(plaintext);
   184→
   185→        // 2. RSA로 AES 키 암호화
   186→        let mut rsa = RSAContext::new();
   187→        let aes_key_ciphertext = rsa.encrypt(&[0x42u8; 32]);
   188→
   189→        // 3. HMAC으로 무결성 검증
   190→        let mut validator = HMACValidator::new(&[0x55u8; 32]);
   191→        let hmac = validator.hmac_sha256(plaintext);
   192→
   193→        // 4. 메모리 정리
   194→        let mut cleaner = MemoryCleaner::new();
   195→        let mut temp_key = [0x42u8; 32];
   196→        cleaner.secure_wipe_key(&mut temp_key);
   197→
   198→        // 전체 검증
   199→        assert!(aes.verify_c14_r1());
   200→        assert!(rsa.verify_c14_r2());
   201→        assert!(validator.verify_c14_r3());
   202→        // ... (나머지 규칙 검증)
   203→
   204→        println!("✅ C14-T6: E2E 통합 테스트 통과");
   205→        println!("   - AES-256 암호화: OK");
   206→        println!("   - RSA-4096 암호화: OK");
   207→        println!("   - HMAC-SHA256 검증: OK");
   208→        println!("   - Memory cleanup: OK");
   209→    }
   210→}
   211→
   212→// ============================================================================
   213→// Challenge 14 통합 검증 함수
   214→// ============================================================================
   215→
   216→pub fn verify_challenge_14_all_rules() {
   217→    println!("\n🔐 Challenge 14: L0-Mail-Core 무관용 규칙 검증\n");
   218→
   219→    let mut aes = AESContext::new(&[0x42u8; 32], &[0x00u8; 16]);
   220→    let mut rsa = RSAContext::new();
   221→    let mut validator = HMACValidator::new(&[0x55u8; 32]);
   222→    let mut key_ctx = KeyDerivationContext::new();
   223→    let mut memory = MemoryCleaner::new();
   224→
   225→    // 각 규칙 검증
   226→    println!("📋 규칙 검증 결과:");
   227→    println!(
   228→        "   C14-R1 (암호화 < 5ms): {}",
   229→        if aes.verify_c14_r1() { "✅" } else { "❌" }
   230→    );
   231→    println!(
   232→        "   C14-R2 (복호화 100%): {}",
   233→        if rsa.verify_c14_r2() { "✅" } else { "❌" }
   234→    );
   235→    println!(
   236→        "   C14-R3 (HMAC 100%): {}",
   237→        if validator.verify_c14_r3() { "✅" } else { "❌" }
