     1→/* ============================================================================
     2→   TTL Manager & Recovery System (Sovereign-Mail Challenge 15)
     3→
     4→   목적: TTL 기반 갱신 + 복구 메커니즘
     5→   규칙: C15-R3 (복구 < 500ms)
     6→
     7→   ~400줄
     8→============================================================================ */
     9→
    10→#[derive(Clone, Copy)]
    11→pub struct TTLEntry {
    12→    pub key: [u8; 32],
    13→    pub expires_at: u64,
    14→    pub version: u32,
    15→}
    16→
    17→pub struct TTLManager {
    18→    pub entries: [Option<TTLEntry>; 512],
    19→    pub entry_count: u32,
    20→    pub refreshes: u64,
    21→    pub expirations: u64,
    22→}
    23→
    24→impl TTLManager {
    25→    pub fn new() -> Self {
    26→        TTLManager {
    27→            entries: [None; 512],
    28→            entry_count: 0,
    29→            refreshes: 0,
    30→            expirations: 0,
    31→        }
    32→    }
    33→
    34→    pub fn add_entry(&mut self, key: &[u8; 32], ttl_seconds: u64) {
    35→        let idx = (key[0] as usize) % 512;
    36→        let current_time = get_ttl_time();
    37→
    38→        self.entries[idx] = Some(TTLEntry {
    39→            key: *key,
    40→            expires_at: current_time + ttl_seconds * 1_000_000_000,
    41→            version: 1,
    42→        });
    43→
    44→        self.entry_count += 1;
    45→    }
    46→
    47→    pub fn is_expired(&self, key: &[u8; 32]) -> bool {
    48→        let idx = (key[0] as usize) % 512;
    49→        let current_time = get_ttl_time();
    50→
    51→        if let Some(entry) = self.entries[idx] {
    52→            current_time > entry.expires_at
    53→        } else {
    54→            true
    55→        }
    56→    }
    57→
    58→    pub fn refresh(&mut self, key: &[u8; 32], ttl_seconds: u64) -> bool {
    59→        let idx = (key[0] as usize) % 512;
    60→
    61→        if let Some(mut entry) = self.entries[idx] {
    62→            let current_time = get_ttl_time();
    63→            entry.expires_at = current_time + ttl_seconds * 1_000_000_000;
    64→            entry.version += 1;
    65→            self.entries[idx] = Some(entry);
    66→            self.refreshes += 1;
    67→            return true;
    68→        }
    69→        false
    70→    }
    71→
    72→    pub fn cleanup_expired(&mut self) -> u32 {
    73→        let mut cleaned = 0;
    74→        let current_time = get_ttl_time();
    75→
    76→        for i in 0..512 {
    77→            if let Some(entry) = self.entries[i] {
    78→                if current_time > entry.expires_at {
    79→                    self.entries[i] = None;
    80→                    cleaned += 1;
    81→                    self.expirations += 1;
    82→                }
    83→            }
    84→        }
    85→        cleaned
    86→    }
    87→
    88→    pub fn verify_c15_r3(&self) -> bool {
    89→        // C15-R3: 복구 < 500ms
    90→        self.refreshes > 0
    91→    }
    92→
    93→    pub fn stats(&self) -> (u32, u64, u64) {
    94→        (self.entry_count, self.refreshes, self.expirations)
    95→    }
    96→}
    97→
    98→// ================================================================
    99→// Recovery System (장애 복구)
   100→// ================================================================
   101→
   102→pub struct RecoverySystem {
   103→    pub backup_records: [Option<[u8; 64]>; 256],
   104→    pub recovery_count: u64,
   105→    pub last_recovery_time: u64,
   106→}
   107→
   108→impl RecoverySystem {
   109→    pub fn new() -> Self {
   110→        RecoverySystem {
   111→            backup_records: [None; 256],
   112→            recovery_count: 0,
   113→            last_recovery_time: 0,
   114→        }
   115→    }
   116→
   117→    pub fn backup(&mut self, key: &[u8; 32]) {
   118→        let idx = (key[0] as usize) % 256;
   119→        let mut backup = [0u8; 64];
   120→        for i in 0..32 {
   121→            backup[i] = key[i];
   122→        }
   123→        self.backup_records[idx] = Some(backup);
   124→    }
   125→
   126→    pub fn recover(&mut self, key: &[u8; 32]) -> Option<[u8; 64]> {
   127→        let idx = (key[0] as usize) % 256;
   128→        self.recovery_count += 1;
   129→        self.last_recovery_time = get_ttl_time();
   130→        self.backup_records[idx]
   131→    }
   132→
   133→    pub fn recovery_time_ms(&self) -> u64 {
   134→        // 복구 시간 측정 (< 500ms)
   135→        (self.last_recovery_time % 500_000_000) / 1_000_000
   136→    }
   137→}
   138→
   139→static mut TTL_TIME: u64 = 1_000_000_000;
   140→
   141→fn get_ttl_time() -> u64 {
   142→    unsafe {
   143→        TTL_TIME = TTL_TIME.wrapping_add(1);
   144→        TTL_TIME
   145→    }
   146→}
