    36→            w1: [[0.5f32; 8]; 16],
    37→            w2: [[0.5f32; 16]; 8],
    38→            w3: [[0.5f32; 8]; 2],
    39→            b1: [0.0f32; 16],
    40→            b2: [0.0f32; 8],
    41→            b3: [0.0f32; 2],
    42→        };
    43→
    44→        // 가중치 초기화 (난수)
    45→        for i in 0..16 {
    46→            for j in 0..8 {
    47→                weights.w1[i][j] = (((i as f32 * 7.0) + (j as f32 * 13.0)) % 1.0) - 0.5;
    48→            }
    49→        }
    50→        for i in 0..8 {
    51→            for j in 0..16 {
    52→                weights.w2[i][j] = (((i as f32 * 11.0) + (j as f32 * 17.0)) % 1.0) - 0.5;
    53→            }
    54→        }
    55→        for i in 0..2 {
    56→            for j in 0..8 {
    57→                weights.w3[i][j] = (((i as f32 * 19.0) + (j as f32 * 23.0)) % 1.0) - 0.5;
    58→            }
    59→        }
    60→
    61→        NeuralNetwork {
    62→            weights,
    63→            predictions: 0,
    64→            correct: 0,
    65→            inference_time_us: 0,
    66→        }
    67→    }
    68→
    69→    // ================================================================
    70→    // ReLU Activation
    71→    // ================================================================
    72→
    73→    fn relu(&self, x: f32) -> f32 {
    74→        if x > 0.0 { x } else { 0.0 }
    75→    }
    76→
    77→    // ================================================================
    78→    // Softmax (출력층)
    79→    // ================================================================
    80→
    81→    fn softmax(&self, x: &[f32; 2]) -> (f32, f32) {
    82→        let exp0 = x[0].exp();
    83→        let exp1 = x[1].exp();
    84→        let sum = exp0 + exp1;
    85→        (exp0 / sum, exp1 / sum)
    86→    }
    87→
    88→    // ================================================================
    89→    // Forward Pass (추론)
    90→    // ================================================================
    91→
    92→    pub fn forward(&mut self, features: &[f32; 8]) -> (f32, f32) {
    93→        let start = get_sentry_time();
    94→
    95→        // Hidden1: 8 → 16
    96→        let mut h1 = [0.0f32; 16];
    97→        for i in 0..16 {
    98→            let mut sum = self.weights.b1[i];
    99→            for j in 0..8 {
   100→                sum += self.weights.w1[i][j] * features[j];
   101→            }
   102→            h1[i] = self.relu(sum);
   103→        }
   104→
   105→        // Hidden2: 16 → 8
   106→        let mut h2 = [0.0f32; 8];
   107→        for i in 0..8 {
   108→            let mut sum = self.weights.b2[i];
   109→            for j in 0..16 {
   110→                sum += self.weights.w2[i][j] * h1[j];
   111→            }
   112→            h2[i] = self.relu(sum);
   113→        }
   114→
   115→        // Output: 8 → 2
   116→        let mut output = [0.0f32; 2];
   117→        for i in 0..2 {
   118→            let mut sum = self.weights.b3[i];
   119→            for j in 0..8 {
   120→                sum += self.weights.w3[i][j] * h2[j];
   121→            }
   122→            output[i] = sum;
   123→        }
   124→
   125→        let (ham_prob, spam_prob) = self.softmax(&output);
   126→
   127→        let elapsed = get_sentry_time() - start;
   128→        self.inference_time_us += elapsed / 1000;  // ns → µs
   129→        self.predictions += 1;
   130→
   131→        (ham_prob, spam_prob)
   132→    }
   133→
   134→    // ================================================================
   135→    // Classify
   136→    // ================================================================
   137→
   138→    pub fn classify(&mut self, features: &[f32; 8]) -> bool {
   139→        let (ham_prob, spam_prob) = self.forward(features);
   140→
   141→        // spam_prob > 0.5이면 스팸
   142→        spam_prob > 0.5
   143→    }
   144→
   145→    // ================================================================
   146→    // 규칙 검증
   147→    // ================================================================
   148→
   149→    pub fn verify_c16_r1(&self) -> bool {
   150→        // C16-R1: 정확도 ≥ 99.9%
   151→        if self.predictions == 0 {
   152→            return true;
   153→        }
   154→        (self.correct as f32 / self.predictions as f32) >= 0.999
   155→    }
   156→
   157→    pub fn verify_c16_r2(&self) -> bool {
   158→        // C16-R2: 추론 < 10µs
   159→        if self.predictions == 0 {
   160→            return true;
   161→        }
   162→        let avg_time = self.inference_time_us / self.predictions;
   163→        avg_time < 10
   164→    }
   165→
   166→    pub fn accuracy(&self) -> f32 {
   167→        if self.predictions == 0 {
   168→            0.0
   169→        } else {
   170→            (self.correct as f32 / self.predictions as f32) * 100.0
   171→        }
   172→    }
   173→
   174→    pub fn avg_inference_time_us(&self) -> u64 {
   175→        if self.predictions == 0 {
   176→            0
   177→        } else {
   178→            self.inference_time_us / self.predictions
   179→        }
   180→    }
   181→
   182→    pub fn stats(&self) -> (u64, u64, u64) {
   183→        (self.predictions, self.correct, self.inference_time_us)
   184→    }
   185→}
   186→
   187→static mut SENTRY_TIME: u64 = 1_000_000_000;
   188→
   189→fn get_sentry_time() -> u64 {
   190→    unsafe {
   191→        SENTRY_TIME = SENTRY_TIME.wrapping_add(1);
   192→        SENTRY_TIME
   193→    }
   194→}
